-- 面试工坊 · 岗位题库种子（issue #1）
-- 按 code MERGE，可重复执行；新增题只追加，改题直接改对应行。
-- type_code 取值：technical / project / scenario / behavior
-- kp_code 与前端岗位画像的 knowledgePoints[].id 对齐（jvm / concurrent / vue …）
-- follow_ups 是 JSON 数组字符串，最多两条预备追问。

-- ============================ Java 后端（20 题）============================
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-jvm-01', 'java', 'jvm', 'technical', '中等', '说说 JVM 的内存区域划分，哪些区域会 OOM，哪些不会。', '程序计数器、虚拟机栈、本地方法栈、堆、方法区（元空间）。PC 不会 OOM；栈会 StackOverflowError；堆与元空间会 OutOfMemoryError。', '["栈溢出和堆溢出分别怎么排查？","元空间为什么会取代永久代？"]', 1, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-jvm-02', 'java', 'jvm', 'technical', '较难', '讲一下双亲委派模型，以及哪些场景会主动打破它。', '类加载请求先交给父加载器，父加载器加载不了才自己加载，保证核心类不被篡改。打破场景：SPI 用线程上下文类加载器（JDBC）、Tomcat 每个 webapp 独立类加载器实现隔离、OSGi 的网状委派。', '["自定义类加载器要实现哪个方法？","热部署为什么能替换类？"]', 2, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-jvm-03', 'java', 'jvm', 'scenario', '较难', '线上一台 Java 服务 CPU 打满，你怎么定位到具体代码？', 'top 找高 CPU 进程 → top -Hp 找高 CPU 线程 → 线程号转十六进制 → jstack 导出栈，搜 nid 定位线程栈；再看是否 GC 线程占满（jstat -gcutil）。GC 导致的话看堆与对象分布，用 jmap 或 MAT 找大对象。', '["如果是 GC 引起的 CPU 高，指标上有什么区别？","arthas 能怎么帮你？"]', 3, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-jvm-04', 'java', 'jvm', 'technical', '中等', '为什么分代收集？新生代和老年代分别适合什么算法？', '对象存活率不同：新生代朝生夕死，用复制算法（Eden + 两块 Survivor），代价小；老年代存活率高，复制会浪费大量空间，用标记-整理或标记-清除。跨代引用靠卡表记录，避免全堆扫描。', '["对象什么时候进老年代？","G1 的 Region 怎么打破物理分代？"]', 4, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-coll-01', 'java', 'collection', 'technical', '中等', 'HashMap 的扩容机制是什么？为什么链表长度到 8 才转红黑树？', '负载因子 0.75，元素数超过容量乘因子就扩容为两倍并 rehash。树化阈值 8 是泊松分布下的极低概率事件，配合退化阈值 6 避免频繁转换；树化还要求容量不小于 64，否则优先扩容。', '["为什么容量必须是 2 的幂？","并发 put 会有什么问题？"]', 5, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-conc-01', 'java', 'concurrent', 'technical', '较难', 'ConcurrentHashMap 在 JDK 1.8 里为什么放弃分段锁？它怎么保证线程安全？', 'CAS 初始化与插入 + synchronized 锁单个桶头节点，锁粒度从 Segment 降到桶；扩容时多线程协助 transfer。相比分段锁，并发度更高、内存更省。', '["size() 为什么是弱一致的？","扩容时并发读写怎么处理？"]', 6, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-conc-02', 'java', 'concurrent', 'technical', '中等', '线程池的核心参数有哪些？拒绝策略怎么选？', 'corePoolSize、maximumPoolSize、keepAliveTime、workQueue、threadFactory、handler。队列满了才扩到最大线程数。四种拒绝策略：AbortPolicy 抛异常、CallerRunsPolicy 回退给调用线程、Discard 静默丢、DiscardOldest 丢最老的；生产上更常见是自定义记录日志并降级。', '["为什么不建议用无界队列？","核心线程会回收吗？"]', 7, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-conc-03', 'java', 'concurrent', 'scenario', '较难', '线上接口偶发卡死，怀疑死锁，你怎么确认并修复？', 'jstack 导出后搜 Found one Java-level deadlock，看互相持有的锁与线程栈；或用 jconsole/arthas thread -b 直接找阻塞源。修复靠统一加锁顺序、缩小锁范围、用 tryLock 带超时。', '["数据库死锁和 JVM 死锁怎么区分？","tryLock 超时后业务该怎么处理？"]', 8, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-conc-04', 'java', 'concurrent', 'technical', '中等', 'volatile 保证了什么、没保证什么？happens-before 怎么解释？', '保证可见性与禁止指令重排，不保证原子性。写 volatile 变量 happens-before 于后续读，配合程序顺序规则就能推出线程间的可见性；i++ 这类读改写仍需 Atomic 或加锁。', '["双重检查锁为什么需要 volatile？","volatile 底层怎么实现内存屏障？"]', 9, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-spring-01', 'java', 'spring', 'technical', '中等', '你项目里 Spring Bean 的循环依赖是怎么解决的？什么情况下解决不了？', '单例 + 字段/设值注入靠三级缓存：singletonObjects、earlySingletonObjects、singletonFactories。构造器注入、prototype 作用域、@Async 代理场景无法解决，直接抛 BeanCurrentlyInCreationException。', '["三级缓存分别存什么？","为什么要 early reference 而不是直接放成品？"]', 10, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-spring-02', 'java', 'spring', 'technical', '较难', '@Transactional 什么情况下会失效？', '同类内部方法自调用（this 调用不走代理）、方法非 public、异常被 catch 吞掉、抛的是检查异常而默认只回滚运行时异常、类没被 Spring 管理、多数据源未指定事务管理器、异步方法内调用。', '["怎么让自调用也生效？","rollbackFor 该怎么配？"]', 11, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-spring-03', 'java', 'spring', 'project', '中等', '讲一个你项目里用到事务传播行为的场景，为什么选那个级别。', '常见答法：主流程 REQUIRED，审计日志用 REQUIRES_NEW 保证主流程回滚也留痕；嵌套子步骤需要局部回滚时用 NESTED（依赖 savepoint，仅 DataSourceTransactionManager 支持）。要说明取舍：REQUIRES_NEW 会挂起外层、占用额外连接。', '["REQUIRES_NEW 用多了会有什么风险？","NESTED 在什么数据库上不可用？"]', 12, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-mysql-01', 'java', 'mysql', 'scenario', '较难', '一张订单表 5000 万行，查询最近 7 天某个用户的订单很慢，你怎么优化？', '建联合索引 (user_id, created_at) 让过滤与排序都能用上；只取需要的列做覆盖索引；避免在索引列上做函数运算；深分页改游标（created_at + id）。数据量再大就冷热分离或按时间分区。', '["为什么不建议单独加 created_at 索引？","深分页 limit 100000,20 怎么优化？"]', 13, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-mysql-02', 'java', 'mysql', 'technical', '中等', '什么是最左前缀原则？什么是覆盖索引？', '联合索引 (a,b,c) 只有从 a 开始连续匹配才能用上后续列；跳过 a 或对 a 做运算会失效（范围查询后的列只能用于过滤不能用于排序）。覆盖索引指查询列都在索引里，不用回表。', '["where a=1 and c=2 能用上哪些列？","explain 里哪些信号说明没走索引？"]', 14, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-mysql-03', 'java', 'mysql', 'technical', '较难', 'MVCC 是怎么实现的？可重复读能不能完全避免幻读？', '每行有隐藏事务 id 与回滚指针，undo log 串成版本链，ReadView 判断可见性。RR 下快照读用同一 ReadView 避免不可重复读；当前读靠间隙锁（next-key lock）防幻读，但快照读与当前读混用、或加锁范围不当仍可能出现。', '["RC 和 RR 的 ReadView 差别在哪？","间隙锁在什么隔离级别下才有？"]', 15, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-redis-01', 'java', 'redis', 'scenario', '中等', '缓存穿透、击穿、雪崩分别是什么？你项目里怎么处理的？', '穿透：查不存在的数据，用空值缓存或布隆过滤器；击穿：热点 key 过期瞬间打穿，用互斥重建或逻辑过期；雪崩：大量 key 同时失效，过期时间加随机、多级缓存、限流降级。', '["布隆过滤器有误判怎么办？","逻辑过期和互斥锁怎么选？"]', 16, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-redis-02', 'java', 'redis', 'technical', '中等', 'RDB 和 AOF 怎么选？混合持久化解决了什么问题？', 'RDB 体积小、恢复快，但可能丢较多数据；AOF 按写命令追加，实时性好但文件大、恢复慢。混合持久化把 RDB 快照与增量 AOF 结合，重启加载更快同时丢失更少。', '["AOF 的 everysec 会丢多少数据？","主从切换时怎么减少丢数据？"]', 17, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-mq-01', 'java', 'mq', 'scenario', '较难', '怎么保证消息不丢、且消费幂等？', '不丢：生产端确认（confirm/同步发送）、Broker 持久化 + 副本、消费端手动 ack。幂等：用业务唯一键做去重表或 Redis setnx，或让操作天然幂等（状态机只允许单向流转）。', '["重复消费和顺序消费冲突吗？","消息积压怎么快速处理？"]', 18, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-micro-01', 'java', 'micro', 'project', '较难', '如果要把你项目里的单体拆成微服务，你会先拆哪一块，边界怎么定？', '按业务能力与数据所有权拆，先拆变化频率高、团队独立负责的模块（如题库/评估），而不是按技术分层拆。要点：一服务一库、跨服务用接口而非共享表、事务改最终一致、先补监控与链路追踪。', '["拆完怎么做分布式事务取舍？","共享表会带来什么问题？"]', 19, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-behavior-01', 'java', 'micro', 'behavior', '中等', '讲一个你和其他同学（同事）意见不一致的例子，最后怎么解决的？', '用 STAR 结构：情境、任务、行动、结果。重点讲怎么用数据或小范围验证说服对方、怎么倾听、事后怎么复盘，而不是「最后我赢了」。', '["如果对方是你的上级，你还会坚持吗？","方案被否但事后证明你是对的，怎么办？"]', 20, TRUE);

-- ============================ Web 前端（20 题）============================
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-js-01', 'frontend', 'js', 'technical', '中等', '说说事件循环里宏任务和微任务的执行顺序，并举例说明。', '执行同步代码 → 清空微任务队列 → 取一个宏任务执行 → 再清空微任务。Promise.then、queueMicrotask、MutationObserver 是微任务；setTimeout、setInterval、I/O、UI 渲染是宏任务。', '["async/await 的 await 后面算微任务吗？","Node 和浏览器的事件循环差异？"]', 21, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-js-02', 'frontend', 'js', 'technical', '较难', '闭包在什么情况下会造成内存泄漏？怎么排查？', '闭包持有对外部变量的引用，若引用链上挂着 DOM 或大对象且长期不释放（如事件监听未解绑、定时器未清除、缓存无上限），就会泄漏。排查用 DevTools Memory 的堆快照对比、Performance 的 detached DOM 检查。', '["弱引用（WeakMap）为什么能帮忙？","Vue 组件里的定时器该怎么处理？"]', 22, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-js-03', 'frontend', 'js', 'technical', '中等', 'this 的指向有哪几种情况？箭头函数为什么不同？', '默认绑定（严格模式 undefined）、隐式绑定（obj.fn）、显式绑定（call/apply/bind）、new 绑定。箭头函数没有自己的 this，词法作用域取定义处的 this，且不能被 call 改变。', '["丢失 this 的常见场景是什么？","class 方法里 this 怎么绑定？"]', 23, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-ts-01', 'frontend', 'ts', 'technical', '中等', 'interface 和 type 有什么区别？什么时候必须用 type？', '两者大多可互换；interface 可声明合并、更适合描述对象契约；type 能表达联合、交叉、映射、条件、模板字面量类型，这些场景必须用 type。', '["类型声明合并有什么用？","泛型约束 extends 是什么含义？"]', 24, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-vue-01', 'frontend', 'vue', 'technical', '较难', 'Vue 3 的响应式为什么用 Proxy 替代 Object.defineProperty？', 'Proxy 能监听新增/删除属性、数组索引赋值、Map/Set 等集合操作，且是惰性代理整个对象；defineProperty 要递归遍历已有属性、无法感知新增属性，Vue 2 只能靠 $set 兜底。代价是 Proxy 不支持 IE。', '["ref 和 reactive 的区别？","依赖收集是怎么触发的？"]', 25, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-vue-02', 'frontend', 'vue', 'technical', '中等', 'ref 和 reactive 该怎么选？什么情况下会丢响应式？', '基本类型用 ref，对象用 reactive 或 ref 均可；解构 reactive 对象会丢响应式（用 toRefs），把响应式对象当普通值传进函数再取出来也可能丢。ref 通过 .value 访问，模板里自动解包。', '["toRefs 和 toRef 的区别？","shallowRef 适合什么场景？"]', 26, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-vue-03', 'frontend', 'vue', 'project', '中等', '你项目里组件之间怎么通信？状态管理是怎么选的？', '父子 props/emit，跨层 provide/inject，全局用 Pinia 或轻量 store。选型理由要讲清：页内状态不放全局、全局状态按域拆分、避免用事件总线导致隐式依赖。', '["什么情况下不该引入状态管理库？","provide/inject 的响应式怎么写？"]', 27, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-vue-04', 'frontend', 'vue', 'scenario', '较难', '一个页面要渲染 1 万条数据，滚动很卡，你怎么优化？', '虚拟列表只渲染可视区；分页或无限滚动；用 v-memo/缓存减少重渲染；避免大对象深响应式（用 shallowRef、Object.freeze）；把高频更新抽成独立组件减少 diff 范围。', '["虚拟列表怎么处理不定高？","为什么要避免在一个大 reactive 里放列表？"]', 28, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-browser-01', 'frontend', 'browser', 'technical', '中等', '从输入 URL 到页面展示，中间发生了什么？尽量完整。', 'URL 解析与缓存检查 → DNS → TCP/TLS → 发 HTTP 请求 → 服务端响应 → 解析 HTML 建 DOM、CSS 建 CSSOM → 布局 → 绘制 → 合成。中途 JS 会阻塞解析（除非 defer/async）。', '["哪些阶段会阻塞渲染？","如何优化首屏？"]', 29, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-browser-02', 'frontend', 'browser', 'technical', '较难', '强缓存和协商缓存怎么配合？为什么改了文件用户还是看到旧版？', '强缓存 Cache-Control（max-age/immutable）命中就不发请求；过期后走协商缓存 ETag/If-None-Match、Last-Modified/If-Modified-Since，命中回 304。静态资源用内容哈希文件名 + 长强缓存，HTML 用 no-cache 走协商，才能发版即生效。', '["为什么 index.html 不能设长强缓存？","ETag 和 Last-Modified 怎么选？"]', 30, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-browser-03', 'frontend', 'browser', 'scenario', '中等', '跨域是怎么产生的？CORS 预检请求在什么条件下触发？', '同源策略限制协议/域名/端口不同的请求。非简单请求（方法非 GET/POST/HEAD，或 Content-Type 非三者之一，或有自定义头）先发 OPTIONS 预检，服务端返回 Allow-Origin/Methods/Headers 才继续。带 cookie 还需要 Allow-Credentials 且 Origin 不能是通配符。', '["开发环境 proxy 能解决跨域的原理？","简单请求会带 cookie 吗？"]', 31, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-css-01', 'frontend', 'css', 'technical', '中等', '标准盒模型和 IE 盒模型有什么区别？BFC 能解决哪些问题？', '标准盒模型 width 只含 content；border-box 含 padding 与 border。BFC 是独立渲染区域，能清除浮动、阻止 margin 合并、避免被浮动元素覆盖；触发方式有 overflow 非 visible、float、绝对定位、display:flow-root。', '["margin 塌陷怎么解决？","flow-root 相比 overflow:hidden 好在哪？"]', 32, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-css-02', 'frontend', 'css', 'technical', '中等', 'Flex 和 Grid 分别适合什么布局？', 'Flex 是一维布局，适合行或列内的对齐与分配（导航、卡片内部）；Grid 是二维，适合整页骨架、卡片墙。实际项目里常组合使用：外层 Grid 定骨架，内层 Flex 排内容。', '["flex:1 的三个值分别是什么？","Grid 的 minmax 怎么用于自适应列？"]', 33, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-build-01', 'frontend', 'build', 'technical', '中等', 'Vite 为什么开发时比 Webpack 快？生产构建也有优势吗？', '开发时利用浏览器原生 ESM，按需编译，不用先打包整图；依赖用 esbuild 预构建。生产构建默认 Rollup，esbuild 只做压缩。热更新基于模块图，改动只重新请求相关模块。', '["Vite 的依赖预构建解决什么问题？","为什么生产不用 esbuild 打包？"]', 34, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-build-02', 'frontend', 'build', 'project', '较难', '项目产物体积很大，你从哪些角度优化？', '先量化：分析包体（rollup-plugin-visualizer）。再动手：路由级动态 import、按需引入组件库、externals 或 CDN 拆大依赖、开启 gzip/brotli、图片走压缩与懒加载、tree-shaking（避免副作用写法）。', '["怎么判断某个依赖值不值得拆出去？","动态 import 后首屏反而变慢怎么办？"]', 35, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-perf-01', 'frontend', 'perf', 'scenario', '较难', '首屏 5 秒，你怎么定位瓶颈并优化？', '先用 Lighthouse/Performance 面板量化：TTFB、FCP、LCP、CLS。网络层看体积与请求数、是否没走缓存；渲染层看是否被同步脚本阻塞、是否大图未压缩；交互层看长任务。优化后以 LCP 与首屏时间对比说明收益。', '["TTFB 高说明什么？","LCP 和 FCP 的区别？"]', 36, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-perf-02', 'frontend', 'perf', 'technical', '中等', '重排和重绘有什么区别？怎么减少？', '重排（布局）是几何属性变化，代价高；重绘是颜色等不影响布局的变化。减少：批量改样式（class 切换）、避免强制同步布局（读写分离）、用 transform/opacity 走合成层、用 documentFragment 批量插入。', '["哪些属性改动只触发合成？","will-change 用多了会怎样？"]', 37, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-sec-01', 'frontend', 'security', 'technical', '中等', 'XSS 有哪几种？前端该怎么防？', '存储型、反射型、DOM 型。前端层面：渲染用户内容用文本插值而不是 innerHTML；必须富文本时用白名单 sanitize；给 cookie 加 HttpOnly；配置 CSP 限制脚本来源；对 URL 参数与 postMessage 来源做校验。', '["CSP 能完全防住 XSS 吗？","富文本编辑器场景怎么取舍？"]', 38, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-sec-02', 'frontend', 'security', 'scenario', '较难', 'CSRF 是怎么发生的？SameSite 和 CSRF Token 各自防住什么？', '攻击者借用用户浏览器的 cookie 向目标站发请求。SameSite=Lax/Strict 限制跨站携带 cookie；CSRF Token 校验请求来自自己的页面（能防 SameSite 覆盖不到的场景）。两者叠加，再用 Origin/Referer 校验更稳。', '["JSON 接口用 Content-Type: application/json 为什么能降低风险？","GET 请求为什么不该做写操作？"]', 39, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-behavior-01', 'frontend', 'security', 'behavior', '中等', '讲一次你和设计师（产品）在方案上分歧较大的经历，最后怎么落地的？', '重点讲怎么把主观分歧转成可判断的标准：先对齐目标和用户场景，再给两个可验证的方案与成本，用小范围数据或原型验证，最后记录决策与复盘。', '["如果对方职位比你高，你怎么表达不同意见？","方案上线后效果不好，你怎么复盘？"]', 40, TRUE);

-- ============================ Java 后端补充：四类各 20 题（issue #1 验收线）============================
-- 目标：technical / project / scenario / behavior 每类 20 题，共 80 题。
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-jvm-05', 'java', 'jvm', 'technical', '中等', '说说类加载的五个阶段，什么情况会触发初始化？', '加载、验证、准备、解析、初始化。准备阶段只给静态变量赋零值，赋初值在初始化阶段执行 clinit。触发初始化：new、访问静态字段或方法、反射、子类初始化前先初始化父类、启动主类。', '["准备阶段和初始化阶段对 static final 的处理有什么不同？","类卸载需要满足什么条件？"]', 41, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-coll-02', 'java', 'collection', 'technical', '中等', 'ArrayList 和 LinkedList 分别在什么场景下用？', 'ArrayList 基于数组，随机访问 O(1)，中间插入删除要移动元素，扩容为 1.5 倍；LinkedList 基于双向链表，头尾操作 O(1)，随机访问 O(n)，每个节点多两个引用。多数场景 ArrayList 更快（缓存友好），当队列用优先 ArrayDeque。', '["Arrays.asList 返回的列表能 add 吗？","ArrayList 扩容 1.5 倍而不是 2 倍的原因是什么？"]', 42, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-coll-03', 'java', 'collection', 'technical', '较难', 'HashMap 为什么线程不安全？JDK 7 和 JDK 8 的表现有什么不同？', 'JDK 7 头插法在并发扩容时可能形成环形链表，get 时死循环、CPU 打满；JDK 8 改尾插不再成环，但并发 put 仍会互相覆盖丢数据、size 不准。并发场景直接用 ConcurrentHashMap。', '["ConcurrentHashMap 为什么不允许 null 键值？","Collections.synchronizedMap 的并发度如何？"]', 43, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-conc-05', 'java', 'concurrent', 'technical', '较难', 'AQS 的工作原理是什么？公平锁和非公平锁差在哪？', 'AQS 用 volatile int state 表示同步状态，用 FIFO 双向队列存等待线程：获取失败入队并 park，释放时唤醒后继。非公平锁上来就 CAS 抢 state，公平锁先检查队列是否有前驱。ReentrantLock、Semaphore、CountDownLatch 都基于它。', '["为什么等待队列要用双向链表？","Condition 的等待队列和同步队列是什么关系？"]', 44, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-conc-06', 'java', 'concurrent', 'technical', '中等', 'ThreadLocal 为什么会内存泄漏？线程池里怎么正确传递上下文？', 'ThreadLocalMap 的 key 是弱引用、value 是强引用；线程池线程长期存活，key 被回收后 value 仍挂在 Map 上，就泄漏。用完必须 remove。InheritableThreadLocal 只在创建子线程时复制，线程池复用不生效，需要 TransmittableThreadLocal。', '["既然 value 会泄漏，为什么 key 还用弱引用？","你项目里用 ThreadLocal 存过什么？"]', 45, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-spring-04', 'java', 'spring', 'technical', '中等', 'Spring AOP 用的是什么代理？什么情况下切面会不生效？', '目标类有接口默认 JDK 动态代理，没接口用 CGLIB 生成子类；Spring Boot 2.x 默认 proxyTargetClass=true 直接走 CGLIB。同类自调用不走代理、final 类或方法无法 CGLIB 代理、对象不是 Spring 管理的 Bean，这几种情况切面都不生效。', '["怎么强制统一用 CGLIB？","事务、缓存、自定义切面的执行顺序怎么控制？"]', 46, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-mysql-04', 'java', 'mysql', 'technical', '中等', '哪些写法会导致索引失效？', '对索引列做函数或运算、隐式类型转换（字符串列传数字）、前导模糊 like 百分号开头、联合索引不满足最左前缀、or 连接了非索引列、优化器判断回表成本高于全表扫描。用 explain 看 type 和 key 确认，不要凭感觉。', '["字符串列传数字为什么会失效？","or 两边都有索引就一定会走索引吗？"]', 47, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-redis-03', 'java', 'redis', 'technical', '中等', '用 Redis 做分布式锁要注意什么？', '加锁用 SET key value NX PX 保证原子性，value 放唯一标识；释放时用 Lua 先比较再删除，避免删掉别人的锁；业务可能超过过期时间就用看门狗续期。主从切换可能丢锁，强一致场景要评估 RedLock 或换 ZooKeeper。', '["为什么释放锁必须用 Lua 脚本？","看门狗续期失败时业务该怎么处理？"]', 48, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-project-01', 'java', 'project', 'project', '中等', '用两分钟介绍你的项目，重点说你负责的部分。', '按「业务是什么-规模多大-我的角色-技术栈-一个亮点」讲：一句话业务，接口量与数据量，负责的模块，Spring Boot 加 MySQL 加 Redis，再挑一个可量化亮点（如某接口 P99 从 800ms 降到 120ms）。', '["这个项目最难的技术点是什么？","如果重做你会改哪里？"]', 49, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-project-02', 'java', 'project', 'project', '中等', '项目里你觉得最难的一个模块是哪个？难在哪？', '选一个能讲清取舍的模块，例如异步任务调度：为什么不用同步、怎么保证多实例不重复执行、失败怎么重试与告警，最后给出效果数据。难点要落在「约束」上，而不是「代码多」。', '["失败重试怎么避免无限重试？","任务执行记录表怎么设计？"]', 50, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-project-03', 'java', 'project', 'project', '中等', '挑一张核心表讲讲你的设计思路。', '先讲实体与关系，再讲字段：主键、业务唯一键、状态字段、创建更新时间、软删除标记；索引按真实查询条件建，避免冗余索引；金额用 decimal，时间统一时区，枚举字段想清楚后续扩展。', '["为什么用软删除？代价是什么？","状态字段用枚举还是字典表？"]', 51, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-project-04', 'java', 'project', 'project', '较难', '你的接口怎么做幂等？举个项目里的例子。', '客户端带幂等键，服务端用唯一索引或 Redis setnx 占位，占位成功才处理；金额与状态类操作再加状态机校验。关键是幂等键与业务唯一约束同源，不能只靠 Redis。', '["幂等键过期了怎么办？","update 接口怎么保证幂等？"]', 52, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-project-05', 'java', 'project', 'project', '较难', '项目里缓存和数据库怎么保持一致？', '用 Cache Aside：先更新库再删缓存，删除失败进重试队列或发消息补偿；给过期时间加随机值减少同时失效。强一致要求高的读路径直接读库或加锁，不要用「先删缓存再更新库」的顺序。', '["延迟双删解决的是什么问题？","缓存删除失败怎么兜底？"]', 53, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-project-06', 'java', 'project', 'project', '中等', '项目里的定时任务是怎么做的？多实例怎么防止重复执行？', '单机用 Scheduled；集群用分布式调度平台（XXL-JOB / Quartz 集群）或数据库行锁、Redis 锁抢占执行权。任务本身必须幂等、可重跑，执行日志落库，失败告警。', '["任务执行时间超过间隔怎么办？","任务分片怎么设计？"]', 54, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-project-07', 'java', 'project', 'project', '中等', '线上出问题你怎么靠日志定位？项目里怎么打日志？', '用 traceId 串起一次请求，关键节点打 info、异常打 error 并带上业务主键与参数摘要；日志分级，注意脱敏与大字段。排查时按 traceId 或时间窗 grep，再结合链路追踪定位到具体环节。', '["日志里不该出现什么？","怎么不重启调整日志级别？"]', 55, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-project-08', 'java', 'project', 'project', '中等', '项目里的权限是怎么设计的？', '认证用 token 或 session，鉴权用 RBAC：用户-角色-权限三张表，接口用拦截器或注解校验，数据权限再按部门或负责人过滤。前端隐藏按钮只是体验，不能当安全边界。', '["RBAC 和 ABAC 怎么选？","水平越权怎么防？"]', 56, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-project-09', 'java', 'project', 'project', '中等', '项目里的文件上传是怎么实现的？', '前端直传对象存储拿预签名 URL，后端只发凭证，避免大文件过应用层；后端校验类型与大小、重命名文件、控制访问权限；大文件用分片上传加秒传。', '["预签名 URL 有什么风险？","怎么防止上传可执行文件？"]', 57, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-project-10', 'java', 'project', 'project', '较难', '你做过哪次接口性能优化？数据怎么来的？', '先压测拿 P99 和瓶颈（CPU、GC、SQL、锁），再改：加索引、消除 N+1 查询、批量接口、非核心逻辑异步化、加缓存、调连接池与线程池。优化后用同一份压测数据对比，说明收益与副作用。', '["压测数据怎么造？","优化后怎么确认没有引入新问题？"]', 58, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-project-11', 'java', 'project', 'project', '中等', '项目里的单元测试怎么写的？覆盖到什么程度？', '服务层测业务分支与异常路径，Controller 用 MockMvc 测参数校验与状态码，外部依赖 mock 掉；集成测试用内存库保证可重复。重点覆盖边界与失败路径，不追求覆盖率数字。', '["mock 太多有什么问题？","事务回滚怎么测？"]', 59, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-project-12', 'java', 'project', 'project', '中等', '你们团队的代码规范和评审是怎么做的？', '统一格式化与命名规范，静态检查（Checkstyle / SpotBugs）进流水线；评审重点看边界条件、异常处理、SQL 与并发；小步提交，一个 PR 只做一件事，评论对事不对人。', '["评审时你最关注什么？","历史代码不规范怎么推进？"]', 60, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-project-13', 'java', 'project', 'project', '较难', '要导出几十万行数据，你怎么做才不拖垮数据库？', '不要一次性查全量，用游标或分页流式写文件；导出改成异步任务，完成后通知下载；限制单次导出量，加权限与频率限制；CSV 注意转义与编码。', '["导出文件很大怎么落盘？","怎么避免导出占满连接池？"]', 61, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-project-14', 'java', 'project', 'project', '中等', '项目里的异常是怎么统一处理的？', '全局异常处理器把业务异常转成统一响应码，系统异常记日志但对外不暴露堆栈；区分可重试与不可重试；不用异常做流程控制，也不 catch 之后什么都不做。', '["为什么不能把堆栈返回给前端？","业务异常该记 error 还是 warn？"]', 62, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-project-15', 'java', 'project', 'project', '中等', '项目的配置和密钥是怎么管理的？', '环境相关配置外置（profile 或配置中心），密钥只从环境变量读，不入库、不进仓库；配置变更可追溯、可回滚；本地提供 example 文件说明必填项。', '["配置中心挂了怎么办？","配置怎么做灰度？"]', 63, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-project-16', 'java', 'project', 'project', '中等', '项目是怎么部署的？回滚怎么做？', '构建、单测、静态检查、镜像打包、部署串成流水线；产物带版本与提交号；回滚保留上一个镜像直接切换；数据库变更脚本随版本管理且向前兼容。', '["怎么做零停机发布？","回滚时数据库脚本怎么处理？"]', 64, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-project-17', 'java', 'project', 'project', '中等', '开发到一半需求变了，你怎么处理？', '先确认变更影响面（接口、表结构、联调、测试用例），评估工时与风险再答复；能拆就拆成迭代；变更写进文档，避免口头需求。', '["变更导致延期怎么和产品沟通？","已上线功能要改怎么控制风险？"]', 65, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-project-18', 'java', 'project', 'project', '中等', '项目里为什么选这个技术？有没有考虑过别的方案？', '看场景约束：团队熟悉度、生态、性能、运维成本；做一个最小原型对比，再给结论与退出成本。不要因为「新」而选，也别因为「旧」而拒，讲清一个真实取舍即可。', '["选错了怎么补救？","怎么说服团队接受你的方案？"]', 66, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-scene-01', 'java', 'jvm', 'scenario', '较难', '线上一台服务 OOM 了，你怎么排查？', '先看日志判断是堆 OOM 还是元空间、直接内存；堆的话靠 HeapDumpOnOutOfMemoryError 拿 dump，用 MAT 看支配树找大对象；元空间查动态代理与类加载器泄漏；直接内存查 Netty 或 NIO 资源未释放。', '["线上没开 dump 参数怎么办？","怎么区分内存泄漏和流量突增？"]', 67, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-scene-02', 'java', 'jvm', 'scenario', '较难', '接口 RT 突然从 50ms 抖到 800ms，你怎么定位？', '分三段看：入口（网络、排队、线程池）、应用（GC、锁、慢日志）、下游（DB、缓存、RPC）。先看 GC 日志与线程池队列，再看下游 P99 与超时重试；定位到具体阶段再改，不要一上来就加机器。', '["GC 停顿怎么量化？","重试风暴怎么避免？"]', 68, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-scene-03', 'java', 'mysql', 'scenario', '中等', '线上慢 SQL 怎么定位和优化？', '开慢查询日志拿到 SQL，explain 看 type、key、rows、Extra；缺索引补联合索引，回表多改覆盖索引，深分页改游标；数据量过大再考虑分区或归档。改完用执行计划对比确认。', '["explain 里 Using filesort 说明什么？","索引建多了有什么坏处？"]', 69, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-scene-04', 'java', 'redis', 'scenario', '较难', '用户反馈看到旧数据，怀疑缓存不一致，你怎么查？', '先判断能否接受短暂不一致；不接受就读写串行或加锁。常规做法是更新库后删缓存，删除失败进重试队列；再加抽样比对监控，对比缓存与库的差异。', '["怎么发现已经不一致了？","热点 key 重建时怎么防击穿？"]', 70, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-scene-05', 'java', 'mq', 'scenario', '中等', '消息被重复消费导致重复扣款，怎么修？', '消费端做幂等：用业务唯一键去重表或状态机校验，处理成功才 ack；重试设上限并进死信队列；不要把正确性建立在「消息只投一次」的假设上。', '["去重表怎么清理？","顺序消息里重复消费怎么处理？"]', 71, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-scene-06', 'java', 'redis', 'scenario', '较难', '秒杀活动怎么防超卖？', '库存预热到 Redis，用 Lua 原子扣减，扣成功再异步落库；数据库用条件更新或乐观锁兜底；入口限流、队列削峰、防刷与一人一单校验。', '["Redis 扣减成功但落库失败怎么办？","怎么防同一用户重复下单？"]', 72, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-scene-07', 'java', 'micro', 'scenario', '较难', '下游服务故障导致我们接口全挂，怎么处理？', '设置合理超时、按失败率熔断、用线程池或信号量隔离、失败降级返回兜底数据；重试加退避与抖动，避免放大流量。目标是「下游挂了，我们还能提供部分能力」。', '["熔断和限流解决的是同一个问题吗？","降级数据怎么避免误导用户？"]', 73, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-scene-08', 'java', 'redis', 'scenario', '中等', '分布式锁的业务执行超时了怎么办？', '锁必须带过期时间防死锁；业务可能超时就靠看门狗定时续期，或把长任务拆短；释放前校验持有者。续期失败要能被业务感知并中止，而不是继续裸奔。', '["看门狗自己挂了怎么办？","等锁超时后应该重试还是直接失败？"]', 74, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-scene-09', 'java', 'spring', 'scenario', '中等', '一个事务里既写库又发消息，怎么保证不出问题？', '事务里不要放 RPC、发消息、大文件处理；缩小事务范围，先校验准备再开短事务更新；必须跨资源时用本地消息表加补偿，或事务消息，而不是长事务。', '["事务里发消息会有什么问题？","怎么发现大事务？"]', 75, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-scene-10', 'java', 'mysql', 'scenario', '中等', '数据库连接池被打满了，你怎么查？', '看活跃连接数、等待线程数与获取连接超时日志；常见原因是慢 SQL、事务未提交、连接泄漏、并发突增。先定位持有者（堆栈与 SQL），再调池大小与超时，最后加监控告警。', '["池越大越好吗？","怎么定位连接泄漏？"]', 76, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-scene-11', 'java', 'micro', 'scenario', '中等', '部署了三台实例，定时任务重复执行了三次，怎么改？', '用分布式调度平台，或数据库行锁、Redis 锁抢占执行权；任务本身做幂等；加执行记录表，用业务日期唯一约束兜底。多实例下不能再用本地 Scheduled。', '["抢锁的实例中途挂了怎么办？","大任务怎么做分片执行？"]', 77, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-scene-12', 'java', 'redis', 'scenario', '中等', '单个热点 key 把 Redis 打满了，怎么办？', '本地缓存加 Redis 两级，热点 key 过期时间加随机避免同时失效；读多写少可以加副本分散；写热点改成异步合并写。先确认是真热点而不是大 key。', '["本地缓存怎么保证一致性？","怎么发现热点 key 和大 key？"]', 78, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-scene-13', 'java', 'mysql', 'scenario', '较难', '要把一张大表迁移到新结构，还不能停机，怎么做？', '双写加双读比对，先灰度切读，确认无差异后再切写，最后下线旧表；迁移脚本要幂等可重跑；全程保留回滚开关并监控差异数。', '["双写失败怎么补偿？","怎么验证两边数据一致？"]', 79, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-scene-14', 'java', 'micro', 'scenario', '中等', '新版本要灰度发布，怎么保证能随时回滚？', '按实例或用户维度灰度，新旧版本接口保持兼容；数据库变更向前兼容（先加字段、不急着删）；回滚只切流量、不依赖回滚数据库，所以变更必须可兼容。', '["灰度期间观察哪些指标？","接口不兼容时怎么发版？"]', 80, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-scene-15', 'java', 'concurrent', 'scenario', '中等', '线程池队列堆了几万个任务，接口越来越慢，怎么处理？', '看队列长度与拒绝次数；先判断是任务变慢还是流量变大。任务变慢查下游与锁，流量变大加限流与扩容；不要盲目调大队列，那只会把延迟藏起来。', '["CallerRunsPolicy 有什么副作用？","线程池该监控哪些指标？"]', 81, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-behavior-02', 'java', 'project', 'behavior', '中等', '讲一个你最有成就感的项目或功能。', '用 STAR：背景交代要短，任务说清你负责的边界，行动讲关键决策与踩坑，结果给可量化数据（用户量、耗时、故障率）。成就感要落在「解决了什么真实问题」上。', '["这个项目里哪部分是你独立完成的？","如果队友不配合你会怎么办？"]', 82, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-behavior-03', 'java', 'project', 'behavior', '较难', '讲一次失败或事故，你从中学到了什么？', '选一个真实、有边界的失败：不要甩锅给别人，也不要选致命错误。讲清根因、你当时的处置、事后补的机制（测试、监控、流程），以及后来怎么避免同类问题。', '["当时有没有更早发现问题的信号？","如果重来一次你会怎么做？"]', 83, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-behavior-04', 'java', 'project', 'behavior', '中等', '你是怎么学一门新技术的？举最近的例子。', '讲闭环：先读官方文档建立概念，再做最小可运行例子，然后读源码或源码级文章解决疑问，最后写笔记或讲给别人听。例子要具体到「学了什么、做了什么、验证了什么」。', '["遇到文档写不清楚的地方怎么办？","怎么判断自己真的学会了？"]', 84, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-behavior-05', 'java', 'project', 'behavior', '中等', '多任务同时压过来、时间不够时你怎么安排？', '先按重要紧急排序，明确截止时间与依赖；主动同步风险而不是硬扛；能拆的拆、能求助的求助；事后复盘估算偏差。重点体现「优先级判断 + 及时沟通」。', '["如果两个都是领导交办的怎么排？","你怎么评估一个任务要多久？"]', 85, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-behavior-06', 'java', 'project', 'behavior', '中等', '讲一次你收到负面反馈的经历。', '先讲反馈内容与当时的感受，再讲你怎么核实、怎么改，最后给改变后的结果。避免「我没错，是对方不理解」的叙事，重点在可观察的行为改变。', '["如果反馈你不认同呢？","你怎么主动去要反馈？"]', 86, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-behavior-07', 'java', 'project', 'behavior', '中等', '你有没有带过新人或帮同学解决技术问题？', '讲一次具体的：对方卡在哪、你怎么判断他的水平、你给了什么提示而不是直接给答案、后来他能不能独立做。体现的是耐心与方法，不是「我很强」。', '["对方学得慢你会怎么调整方式？","你会不会担心被超过？"]', 87, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-behavior-08', 'java', 'project', 'behavior', '中等', '讲一次跨团队或跨专业协作的经历。', '讲清目标不一致时怎么对齐、接口和交付物怎么定、出问题时怎么推进；可以讲和前端对接口字段、和产品对需求范围的具体例子，结果要给「按时交付」这类客观事实。', '["对方拖延导致你延期怎么办？","协作中你一般扮演什么角色？"]', 88, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-behavior-09', 'java', 'project', 'behavior', '较难', '如果领导安排了一个你认为不合理的需求，你会怎么做？', '先理解需求背后的目标，再指出具体风险与成本，给出替代方案；决策权在对方时执行并留下风险记录。关键是「先对齐目标再谈方案」，不是直接拒绝。', '["如果对方坚持原方案呢？","你怎么判断一个需求是否合理？"]', 89, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-behavior-10', 'java', 'project', 'behavior', '中等', '你平时怎么管理自己的时间？', '讲具体机制：任务清单与截止时间、按精力分配深度工作、每天留缓冲处理突发、每周复盘。避免空泛地说「我很自律」，给一个真实在用的小工具或习惯。', '["计划总被打断怎么办？","你怎么处理拖延？"]', 90, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-behavior-11', 'java', 'project', 'behavior', '中等', '你未来三年的职业规划是什么？', '分阶段讲：一年内把岗位基础能力打扎实并能独立负责模块，两到三年在某个方向（如高并发、中间件、架构）形成专长，长期做技术深度与业务理解的结合。规划要与岗位匹配且可执行。', '["如果公司没法提供这个方向的机会呢？","你怎么衡量自己每年有没有进步？"]', 91, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-behavior-12', 'java', 'project', 'behavior', '中等', '说说你的优点和缺点，各举一个例子。', '优点选与岗位相关的（如拆解问题、靠谱交付），用事例证明；缺点选真实但不致命的（如公开表达紧张、前期过度追求细节），重点讲你正在用什么方法改善。', '["这个缺点影响过工作吗？","同事会怎么评价你？"]', 92, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-behavior-13', 'java', 'project', 'behavior', '中等', '你为什么选择做后端开发？', '从真实经历出发：做过什么让你觉得有意思（如把接口从 2 秒优化到 200ms）、喜欢哪类问题（数据、并发、稳定性）、为此投入了什么学习。不要只说「后端有前途」。', '["如果让你转前端你愿意吗？","你了解我们岗位做什么吗？"]', 93, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-behavior-14', 'java', 'project', 'behavior', '较难', '讲一个你排查最久的 bug，最后怎么找到的？', '讲清现象、排除过程、关键线索怎么来的（日志、二分、最小复现），以及根因是什么。重点体现方法论：先缩小范围、再做对照实验、最后沉淀成检查项。', '["如果始终找不到根因你会怎么办？","这个 bug 后来怎么防复发？"]', 94, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-behavior-15', 'java', 'project', 'behavior', '中等', '讲一次你被误解或背锅的经历，你怎么处理的？', '先摆事实（日志、记录、时间线），再私下沟通而非群里对线；如果确实有自己一部分责任就认下来。结果要落在「问题解决 + 关系没坏」上，而不是证明自己清白。', '["如果对方不承认怎么办？","事后你会怎么留痕？"]', 95, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-behavior-16', 'java', 'project', 'behavior', '中等', '有没有主动做过职责之外的事？', '讲一件你发现但没人安排的事：如补监控告警、写部署文档、清理历史脏数据。说清你为什么觉得该做、怎么在不影响本职的前提下推进、带来了什么改变。', '["怎么平衡本职和额外工作？","如果没人认可你还会做吗？"]', 96, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-behavior-17', 'java', 'project', 'behavior', '中等', '面对长期重复、枯燥的任务，你怎么保持状态？', '讲怎么把重复任务自动化或模板化、怎么给自己设阶段目标、怎么从重复中提炼改进点。给出一个真实例子，比如把手工回归整理成脚本。', '["自动化投入的时间值得吗？","你会不会因为枯燥想换工作？"]', 97, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-behavior-18', 'java', 'project', 'behavior', '中等', '你怎么看待加班？', '表达可承接高强度阶段（如上线、故障），同时说明你会靠计划和复盘减少无效加班；不抱怨也不空喊「随便加」。可以举一次赶项目的真实经历与事后调整。', '["如果是长期加班呢？","你怎么判断加班是必要的？"]', 98, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-behavior-19', 'java', 'project', 'behavior', '中等', '最近有关注什么技术趋势？对你有什么影响？', '选一个你真读过、能讲清边界的方向（如虚拟线程、GraalVM、AI 辅助编码），说清它解决什么问题、目前限制在哪、你有没有动手试过。不要背新闻标题。', '["你试过之后结论是什么？","它会取代现有方案吗？"]', 99, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('java-behavior-20', 'java', 'project', 'behavior', '中等', '你有什么问题想问我们？', '问能体现思考的问题：团队当前的技术重点与痛点、这个岗位前三个月的目标、代码评审与发布流程、新人培养方式。避免一上来问薪资假期。', '["你更看重成长还是稳定？","你希望遇到什么样的leader？"]', 100, TRUE);

-- ============================ Web 前端补充：四类各 20 题（issue #1 验收线）============================
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-js-04', 'frontend', 'js', 'technical', '中等', '说说原型链，以及 ES6 class 继承和寄生组合继承的关系。', '每个对象有 __proto__ 指向构造函数的 prototype，查找属性沿这条链向上直到 null。class 的 extends 本质仍是原型链，super 调用父构造器；寄生组合继承就是「子类原型指向父类原型副本 + 修正 constructor」，是目前最完整的组合方式。', '["instanceof 的判断依据是什么？","为什么不能直接 Child.prototype = Parent.prototype？"]', 101, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-js-05', 'frontend', 'js', 'technical', '中等', '防抖和节流有什么区别？分别用在什么场景？', '防抖是停止触发后延迟执行一次，适合搜索联想、窗口 resize；节流是固定间隔最多执行一次，适合滚动监听、拖拽、上报。防抖会「等安静」，节流会「按频率放行」，选错会导致该响应的场景没响应。', '["防抖怎么加立即执行选项？","节流用时间戳和定时器实现有什么区别？"]', 102, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-ts-02', 'frontend', 'ts', 'technical', '中等', '讲讲 TypeScript 泛型和常用的工具类型。', '泛型让类型参与参数化，调用时推断或显式指定，约束用 extends。常用工具类型：Partial、Required、Pick、Omit、Record、ReturnType、Parameters、Readonly；理解它们基于映射类型与条件类型实现，才能自己写业务工具类型。', '["infer 用在什么场景？","泛型默认值和重载怎么配合？"]', 103, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-vue-05', 'frontend', 'vue', 'technical', '中等', 'nextTick 是什么？为什么改了数据马上读 DOM 拿不到新值？', 'Vue 的更新是异步批量的：数据变更只标记依赖，等微任务队列里统一 patch。nextTick 就是把回调排到这次 DOM 更新之后。需要读新 DOM 尺寸或聚焦时用 await nextTick，不要用 setTimeout 硬等。', '["nextTick 在 Vue 3 里基于什么实现？","什么场景必须用 nextTick？"]', 104, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-browser-04', 'frontend', 'browser', 'technical', '中等', 'Cookie、localStorage、sessionStorage、IndexedDB 怎么选？', 'Cookie 随请求自动发送、容量约 4KB，放会话凭证并设 HttpOnly；localStorage 约 5MB、长期留存、同步 API，适合非敏感偏好；sessionStorage 仅当前标签页；IndexedDB 容量大、异步、可建索引，适合离线数据与大量缓存。', '["localStorage 存 token 有什么风险？","为什么前端缓存要设版本号？"]', 105, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-css-03', 'frontend', 'css', 'technical', '中等', '水平垂直居中你一般怎么写？层叠上下文是怎么形成的？', '居中：Flex 的 align-items 加 justify-content 最通用；Grid 的 place-items；绝对定位加 transform；单行文本用 line-height。层叠上下文由 position 加 z-index、opacity 小于 1、transform、filter、flex 子项的 z-index 等触发，内部层级不与外部比较。', '["z-index 为什么会失效？","position: fixed 在 transform 父元素里为什么像 absolute？"]', 106, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-build-03', 'frontend', 'build', 'technical', '中等', 'ESM 和 CommonJS 有什么区别？为什么打包工具要处理互操作？', 'ESM 是静态结构，编译时就能确定依赖、支持 tree-shaking、导出是活绑定；CommonJS 运行时 require、导出是值的拷贝。两者加载时机与循环依赖表现不同，所以打包器要做 interop，把 CJS 包包装成默认导出。', '["为什么有些库打包后 tree-shaking 失效？","import() 动态导入返回什么？"]', 107, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-project-01', 'frontend', 'vue', 'project', '中等', '用两分钟介绍你的前端项目，重点说你负责的部分。', '按「业务-用户量-你的角色-技术栈-一个亮点」讲：一句话业务，页面数与日活，负责的模块，Vue 3 加 Vite 加 Pinia，再挑一个可量化亮点（如首屏从 4s 降到 1.8s）。', '["这个项目最难的地方是什么？","如果重做你会改哪里？"]', 108, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-project-02', 'frontend', 'vue', 'project', '中等', '项目里的组件是怎么拆分的？怎么保证复用？', '按职责与变化频率拆：展示组件只收 props、容器组件管数据；通用能力抽成基础组件并沉淀 props 与事件契约；跨页面复用的逻辑抽 composable。避免为了复用把不相关的东西塞进一个万能组件。', '["什么时候不该抽组件？","基础组件怎么做版本管理？"]', 109, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-project-03', 'frontend', 'vue', 'project', '中等', '为什么选 Pinia 而不是 Vuex？状态怎么划分？', 'Pinia 没有 mutations、TS 推断好、支持组合式写法、模块天然隔离；Vuex 模板代码多且类型支持弱。状态按业务域拆 store，页内状态留在组件里，不把表单临时值放进全局。', '["什么状态不该放全局？","store 之间互相依赖怎么处理？"]', 110, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-project-04', 'frontend', 'vue', 'project', '中等', '项目里的路由权限是怎么做的？', '登录后拿角色与权限码，路由守卫在进入前校验 meta 权限，无权限跳 403；动态路由按权限注册；按钮级权限用指令或函数控制显隐。前端控制只是体验，接口必须二次校验。', '["刷新后动态路由丢失怎么办？","权限变更怎么让用户立即生效？"]', 111, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-project-05', 'frontend', 'js', 'project', '中等', '项目里的请求层是怎么封装的？', '统一实例配 baseURL、超时、拦截器：请求带 token，响应统一处理业务码与错误提示；401 走刷新或跳登录；并发重复请求做取消或合并；类型用泛型约束返回值。错误提示与业务解耦。', '["怎么取消重复请求？","401 刷新 token 时怎么避免并发多次刷新？"]', 112, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-project-06', 'frontend', 'vue', 'project', '中等', '复杂表单你怎么做校验和联动？', '把校验规则与字段定义抽成配置，动态表单按配置渲染；联动用 watch 或计算属性控制显隐与必填；提交前统一校验并滚动定位到第一个错误；服务端错误按字段回填。避免每个字段写一遍重复逻辑。', '["动态删字段后校验怎么清理？","异步校验怎么防抖？"]', 113, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-project-07', 'frontend', 'perf', 'project', '较难', '项目里的大表格是怎么做性能优化的？', '先量化行数与卡顿点。手段：虚拟滚动只渲染可视区、固定列宽减少重排、分页或懒加载、单元格组件化与 v-memo 减少 diff、避免在模板里做重计算、大数据用 shallowRef 减少响应式开销。', '["虚拟滚动怎么处理行高不定？","什么情况下该改成分页？"]', 114, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-project-08', 'frontend', 'css', 'project', '中等', '项目的主题切换（暗色模式）是怎么实现的？', '颜色统一走 CSS 变量，切换时只改根节点上的主题类；首屏用内联脚本读本地偏好避免闪烁；组件不写死色值；跟随系统用 prefers-color-scheme。', '["怎么避免刷新时白屏闪一下？","主题色要做运行时自定义怎么办？"]', 115, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-project-09', 'frontend', 'vue', 'project', '中等', '项目有多语言需求，你怎么做国际化？', '文案抽到语言包，按 key 取；请求头或本地存储决定语言；日期数字用 Intl 格式化；语言包按路由懒加载；避免在模板里拼中文句子，注意词序与复数规则。', '["文案里带变量怎么处理？","语言包很大怎么优化？"]', 116, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-project-10', 'frontend', 'css', 'project', '中等', '移动端适配你是怎么做的？', '视口 meta 加 rem 或 vw 方案按设计稿等比缩放；1px 边框用 transform 缩放或伪元素；安全区用 env；交互注意点击热区不小于 44px。不要混用多套缩放方案。', '["rem 和 vw 方案各有什么坑？","横屏和折叠屏怎么处理？"]', 117, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-project-11', 'frontend', 'browser', 'project', '中等', '线上前端报错你怎么发现和定位？', '接 window.onerror、unhandledrejection、资源加载错误，上报时带页面、版本、用户环境与堆栈；sourcemap 上传到错误平台还原；按版本和错误指纹聚合，先看新增错误而不是总量。', '["sourcemap 放公网有什么风险？","怎么区分用户环境问题和代码问题？"]', 118, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-project-12', 'frontend', 'build', 'project', '中等', '前端的构建和部署流程是怎样的？', '本地 lint 与类型检查 → 构建产物带内容哈希 → 静态资源上传 CDN → HTML 灰度或全量替换；环境变量区分接口地址；发布后可回滚到上一版产物。关键是 HTML 不长缓存、资源长缓存。', '["怎么做前端灰度？","回滚要多久？"]', 119, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-project-13', 'frontend', 'build', 'project', '中等', '团队里怎么统一代码风格？', 'ESLint 加 Prettier 配共享配置，提交前 lint-staged 只检查改动文件；CI 再跑一次兜底；规则分歧靠团队约定而不是各改各的。对历史代码可以逐步放开，不要一次全量格式化冲掉 blame。', '["规则太严会不会影响效率？","怎么处理第三方代码的告警？"]', 120, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-project-14', 'frontend', 'js', 'project', '中等', '前端项目里你写过哪些测试？', '工具函数与 composable 用 Vitest 写单测；组件用 Vue Test Utils 测交互与渲染；关键流程用 Playwright 做端到端。优先覆盖纯逻辑与回归成本高的路径，不为凑覆盖率写无效断言。', '["组件测试和 E2E 怎么分工？","怎么测异步请求？"]', 121, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-project-15', 'frontend', 'vue', 'project', '较难', '项目里最复杂的组件通信场景是什么？怎么解的？', '比如三层嵌套的表单向导：父传子用 props，子通知父用 emit，跨层用 provide/inject 或 Pinia；需要双向同步时用 v-model 约定。重点讲为什么不用事件总线，以及怎么避免隐式依赖。', '["provide/inject 怎么保持响应式？","什么情况下该升级成全局状态？"]', 122, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-project-16', 'frontend', 'vue', 'project', '中等', '开发到一半设计稿大改，你怎么处理？', '先评估改动范围（组件、交互、接口），拆出必须本次做的与可以后续补的；复用已有组件减少重写；及时同步工期风险；把设计变更记录到需求文档，避免反复返工。', '["怎么减少设计变更带来的返工？","工期压不下怎么办？"]', 123, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-project-17', 'frontend', 'vue', 'project', '中等', 'Vue 和 React 你会怎么选？', '看团队与场景：Vue 模板上手快、官方方案齐全，适合中小团队快速交付；React 生态与灵活度更高，适合复杂交互与跨端。别只说「Vue 简单」，要讲清依赖、状态管理、脚手架的成熟度与团队成本。', '["如果团队没人会 React 怎么办？","你更看重框架的哪一点？"]', 124, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-project-18', 'frontend', 'perf', 'project', '较难', '你做过的性能优化，带来了多少可量化的收益？', '用指标说话：优化前后 LCP、首屏时间、包体积、长任务数量。讲清做了什么（路由懒加载、图片压缩、依赖拆分、虚拟列表）以及代价（首屏请求变多、缓存策略变复杂），不要只说「变快了」。', '["怎么证明收益不是网络波动带来的？","优化后有没有引入新问题？"]', 125, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-scene-01', 'frontend', 'browser', 'scenario', '较难', '用户反馈页面白屏，你怎么排查？', '先看控制台报错与资源加载失败（Network 里 404 或 MIME 错误）；确认是构建产物问题还是运行时异常；用错误上报看是否集中在某个版本或浏览器；sourcemap 还原堆栈。常见根因是资源路径错误、某个 chunk 加载失败、首屏接口异常导致渲染中断。', '["怎么给白屏加自动监控？","chunk 加载失败怎么自动恢复？"]', 126, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-scene-02', 'frontend', 'js', 'scenario', '较难', '单页应用用久了越来越卡，怀疑内存泄漏，怎么查？', '用 Performance 看内存曲线是否持续上升；DevTools Memory 抓两次堆快照对比新增对象，重点看 detached DOM；常见泄漏源是未解绑的事件监听、未清理的定时器、全局缓存无上限、闭包持有大对象。', '["怎么定位到具体组件？","路由切走后组件怎么确保释放？"]', 127, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-scene-03', 'frontend', 'perf', 'scenario', '较难', '一个列表滚动明显掉帧，怎么定位和优化？', '用 Performance 录制看是脚本耗时、布局还是绘制；列表长就上虚拟滚动；每项组件化并避免整表重渲染；滚动事件用节流；图片懒加载与固定尺寸避免布局抖动；动画用 transform 走合成层。', '["怎么判断是 JS 还是渲染卡？","虚拟列表滚动跳跃怎么处理？"]', 128, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-scene-04', 'frontend', 'js', 'scenario', '中等', '用户连点提交按钮，产生了多条重复订单，怎么修？', '前端提交时禁用按钮并加 loading；请求层对同一业务键做去重或取消；后端接口做幂等（唯一键或 token）。前端拦截只是体验，正确性必须靠后端幂等兜底。', '["网络慢时用户刷新页面怎么办？","前端按钮禁用能算幂等吗？"]', 129, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-scene-05', 'frontend', 'browser', 'scenario', '中等', '线上突然大量 CORS 报错，怎么查？', '看预检 OPTIONS 是否 4xx、响应头是否缺 Allow-Origin 或 Allow-Credentials；确认请求 Origin 是否在允许列表；检查网关或代理是否吞掉了响应头；带 cookie 时 Origin 不能是通配符。', '["为什么本地开发正常、线上报错？","预检结果会被缓存吗？"]', 130, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-scene-06', 'frontend', 'browser', 'scenario', '中等', '发版后用户说还是旧页面，怎么办？', '确认 index.html 是否被强缓存（应 no-cache 走协商），静态资源是否用内容哈希文件名；用版本号或构建时间去核对线上线下；必要时提示用户刷新或做版本检测弹窗。', '["怎么在不打扰用户的前提下提示更新？","CDN 缓存怎么主动刷新？"]', 131, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-scene-07', 'frontend', 'css', 'scenario', '中等', '移动端弹层关闭后，底下的按钮被误触了，怎么解决？', '点击穿透常见于 touch 结束后又触发 click。方案：用 click 而不是 touchend 处理关闭、关闭时短暂禁用 pointer-events、遮罩层阻止事件穿透、或用 fastclick 类库统一处理。', '["pointer-events 禁用期间怎么避免闪动？","为什么 iOS 上更明显？"]', 132, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-scene-08', 'frontend', 'perf', 'scenario', '中等', '页面图片很多，加载很慢，怎么优化？', '按场景选格式（WebP 或 AVIF 加降级），用 srcset 与 sizes 适配分辨率；非首屏懒加载；固定宽高或占位避免布局抖动；CDN 压缩与缓存；小图用雪碧图或 iconfont 减少请求。', '["懒加载怎么避免影响 SEO？","图片 CDN 参数怎么设才不糊？"]', 133, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-scene-09', 'frontend', 'vue', 'scenario', '中等', '从列表进详情再返回，怎么保留滚动位置和筛选条件？', '列表状态放路由 query 或 Pinia，返回时恢复；滚动位置按路由记到内存或 keep-alive 的 activated 里恢复；长列表建议分页或游标，避免恢复时重新拉全量。', '["keep-alive 会带来什么副作用？","多标签页场景怎么隔离状态？"]', 134, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-scene-10', 'frontend', 'build', 'scenario', '中等', '组件之间互相引用导致循环依赖报错，怎么处理？', '把共享的类型或常量抽到独立模块；用动态 import 延迟加载；或者调整依赖方向，让上层组件编排而不是底层互相引用。循环依赖往往是拆分边界的信号，先看职责是否混淆。', '["动态 import 会不会影响首屏？","类型循环引用也会报错吗？"]', 135, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-scene-11', 'frontend', 'build', 'scenario', '中等', '打包上线后样式错乱，本地却正常，怎么查？', '常见原因：CSS 顺序被抽取后变化、scoped 选择器没生效、postcss 前缀缺失、CDN 缓存了旧 CSS、样式被 tree-shaking 误删。对比线上线下产物哈希，检查构建配置与浏览器兼容目标。', '["CSS 顺序不稳定怎么固定？","怎么确认是缓存问题？"]', 136, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-scene-12', 'frontend', 'js', 'scenario', '较难', '搜索框连续输入，结果却显示成上一次的关键词，怎么修？', '典型的请求竞态：后发先至会覆盖新结果。方案：记录请求序号只采纳最新一次、用 AbortController 取消旧请求、或对输入做防抖并丢弃过期响应。', '["AbortController 取消后后端还会执行吗？","防抖时长怎么定？"]', 137, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-scene-13', 'frontend', 'perf', 'scenario', '较难', '首屏要 5 秒，老板要你一周内降下来，你怎么做？', '先量化：Lighthouse 拿 TTFB、FCP、LCP，Network 看首屏关键请求。先做收益最大的：服务端渲染或骨架屏、路由懒加载、首屏接口合并或并行、图片与字体优化、CDN 与 gzip。按周给对比数据。', '["没有服务端资源时还能做什么？","怎么证明不是用户网络差？"]', 138, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-scene-14', 'frontend', 'browser', 'scenario', '中等', '某个功能只在旧版浏览器出问题，怎么排查和兜底？', '确认目标浏览器范围与构建目标（browserslist）；用 caniuse 查 API 支持；必要时加 polyfill 或降级方案；在错误上报里带上 UA，按浏览器维度聚合看影响面。', '["polyfill 会增加多少体积？","怎么决定还要不要兼容某个版本？"]', 139, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-scene-15', 'frontend', 'vue', 'scenario', '中等', '刷新页面后，有权限的按钮闪一下就消失了，怎么修？', '权限码是异步拿的，首屏按默认无权限渲染了。方案：权限加载完成前延迟渲染受控区域或显示骨架；路由守卫里先取权限再放行；权限状态持久化但以接口返回为准。', '["权限接口失败时怎么处理？","怎么避免整页都被阻塞？"]', 140, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-scene-16', 'frontend', 'browser', 'scenario', '较难', '面试间用 SSE 接收 AI 流式回复，网络波动后断开了怎么办？', '监听 EventSource 的 error 做指数退避重连，并带上最后一条消息序号请求续传；服务端支持按序号补发；页面不可见或长时间无数据要能恢复；降级方案是轮询或一次性拉取完整回复。', '["SSE 和 WebSocket 怎么选？","断线期间的消息怎么保证不丢？"]', 141, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-behavior-02', 'frontend', 'vue', 'behavior', '中等', '讲一个你最有成就感的前端项目或功能。', '用 STAR：业务背景一句话，任务说清你负责的页面与边界，行动讲关键决策（组件拆分、性能优化、交互细节），结果给出可量化数据（首屏、转化、缺陷率）。', '["哪部分是你独立完成的？","这个功能现在还在用吗？"]', 142, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-behavior-03', 'frontend', 'vue', 'behavior', '较难', '讲一次线上事故或明显的失误，你怎么处理的？', '讲清现象、影响面、你的第一反应（止血优先）、根因和事后机制（监控、回归用例、发布检查）。不甩锅，也不把「小失误」包装成事故。', '["当时有没有更早的预警？","后来同类问题还发生过吗？"]', 143, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-behavior-04', 'frontend', 'vue', 'behavior', '中等', '前端技术更新很快，你怎么跟进？', '讲固定信息源（官方文档、RFC、源码）加动手验证：看到新特性先写小 demo，再判断是否适合项目。举一个具体例子，如学了某个 Vue 3 特性后在项目里用上或明确不用。', '["怎么过滤营销味很重的内容？","学过但没用上的技术你怎么看？"]', 144, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-behavior-05', 'frontend', 'vue', 'behavior', '中等', '同时有多个页面要交付、时间不够，你怎么排？', '按业务价值与阻塞关系排序，把可并行的拆出来；主动同步风险与本版砍掉的范围；用组件与配置复用减少重复劳动；事后复盘工期估算偏差。', '["砍功能时怎么和产品达成一致？","你怎么估前端工时？"]', 145, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-behavior-06', 'frontend', 'vue', 'behavior', '中等', '讲一次别人指出你代码问题的经历。', '讲具体问题（如副作用没清理、状态放错层级），你怎么核实、怎么改、后来怎么形成习惯。体现的是接受反馈的速度与改进的持续性。', '["如果不认同评审意见呢？","你会主动请人 review 吗？"]', 146, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-behavior-07', 'frontend', 'vue', 'behavior', '中等', '有没有带过新人或给同学讲过前端知识？', '讲一次具体辅导：对方卡在什么概念、你怎么用类比或小例子拆解、有没有让他自己动手验证。结果看他后来能不能独立完成同类任务。', '["讲不明白时你会怎么办？","你会怎么安排新人的第一个任务？"]', 147, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-behavior-08', 'frontend', 'vue', 'behavior', '中等', '讲一次和设计师或后端协作不顺的经历。', '讲清分歧点（交互还原度、接口字段、联调时间），你怎么用截图、原型或接口文档把问题具体化，最后怎么达成一致并避免再发生。', '["对方坚持不改你怎么办？","怎么减少联调返工？"]', 148, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-behavior-09', 'frontend', 'vue', 'behavior', '较难', '产品要求做一个你认为体验很差的功能，你会怎么做？', '先理解业务目标，再用用户场景和数据说明风险，给替代方案或分阶段方案；决策权不在你时执行并埋点观察，用数据复盘而不是情绪对抗。', '["如果数据证明你错了呢？","怎么在有限时间里做体验兜底？"]', 149, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-behavior-10', 'frontend', 'vue', 'behavior', '中等', '你怎么安排一天的工作？', '讲具体习惯：上午做需要专注的编码，下午处理沟通与联调，任务用清单管理，给突发问题留缓冲；每天结束前同步进度。避免「我很努力」这类空话。', '["被会议打断怎么办？","你怎么处理拖延？"]', 150, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-behavior-11', 'frontend', 'vue', 'behavior', '中等', '你未来三年的规划是什么？', '分阶段：一年内独立负责模块并能做技术方案，两到三年在工程化或性能方向形成专长，长期做业务与技术的结合。规划要能落到具体动作上。', '["如果公司没有这个方向的机会呢？","你怎么衡量自己的成长？"]', 151, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-behavior-12', 'frontend', 'vue', 'behavior', '中等', '说说你的优点和缺点。', '优点选岗位相关的（如对细节和还原度敏感、能把复杂交互拆清楚），用例子支撑；缺点选真实且可改善的（如对非视觉问题关注不足），讲正在用什么方法补。', '["这个缺点影响过交付吗？","同事会怎么评价你？"]', 152, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-behavior-13', 'frontend', 'vue', 'behavior', '中等', '你为什么想做前端？', '从真实体验出发：做过什么让你觉得有成就感（如把复杂表格做流畅、把交互打磨顺），喜欢哪类问题（视觉、交互、工程化），为此学了什么。不要只说「前端入门快」。', '["如果让你做后端你愿意吗？","你了解我们产品吗？"]', 153, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-behavior-14', 'frontend', 'vue', 'behavior', '较难', '讲一个你排查最久的前端问题。', '讲清现象、排除路径（对比环境、二分注释、抓包看请求）、关键线索（版本差异、浏览器差异），以及最后根因。重点体现方法而不是运气。', '["如果一直复现不了怎么办？","后来怎么防止再出现？"]', 154, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-behavior-15', 'frontend', 'vue', 'behavior', '中等', '讲一次你被误解的经历，你怎么处理的？', '先用事实（录屏、日志、提交记录）澄清，再私下沟通避免公开对立；如果自己有责任就认下来。结果落在问题解决与关系维护上。', '["对方不认账怎么办？","事后你会怎么留痕？"]', 155, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-behavior-16', 'frontend', 'vue', 'behavior', '中等', '有没有主动做过职责之外的事？', '例如补了前端错误监控、整理了组件使用文档、把重复的手工回归做成脚本。讲清你为什么觉得该做、怎么控制不影响本职、带来了什么改变。', '["怎么平衡额外工作和本职？","没人认可你还会做吗？"]', 156, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-behavior-17', 'frontend', 'vue', 'behavior', '中等', '做重复的切图或改文案类需求，你怎么保持状态？', '把重复工作模板化或组件化，沉淀设计规范与复用片段；给自己设小目标（如把某个页面的还原耗时减半）；从重复里提炼可改进的工程问题。', '["自动化投入值得吗？","觉得没成长时你会怎么办？"]', 157, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-behavior-18', 'frontend', 'vue', 'behavior', '中等', '你怎么看待加班？', '说明能承接上线与故障期的高强度，同时讲你会靠计划与复盘减少无效加班；可以举一次赶版本的真实经历和事后调整。不抱怨也不空喊口号。', '["长期加班你会怎么应对？","你怎么判断加班是否必要？"]', 158, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-behavior-19', 'frontend', 'vue', 'behavior', '中等', '最近关注了什么前端新技术？', '选你真动手试过的方向（如 Vue 3.4 的响应式优化、Vite 生态、RSC、AI 辅助编码），讲清解决什么问题、限制在哪、是否适合当前项目。不要背标题。', '["你试完的结论是什么？","会在项目里落地吗？"]', 159, TRUE);
MERGE INTO interview_question (code, job_code, kp_code, type_code, difficulty, question_text, reference_answer, follow_ups, sort_order, enabled) KEY(code) VALUES ('fe-behavior-20', 'frontend', 'vue', 'behavior', '中等', '你有什么想问我们的？', '问团队的技术方向与协作方式、这个岗位前三个月的目标、设计还原与开发的协作流程、前端工程化现状。避免只问薪资和假期。', '["你更看重成长还是稳定？","你希望什么样的团队氛围？"]', 160, TRUE);
